describe('Product Sorting by Price - Low to High', () => {
  const username = 'standard_user';
  const password = 'secret_sauce';
  const loginUrl = 'https://www.saucedemo.com';

  beforeEach(() => {
    cy.visit(loginUrl);
    cy.get('[data-test="username"]').type(username);
    cy.get('[data-test="password"]').type(password);
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-test="inventory-container"]').should('be.visible');
  });

  it('should sort products by price in ascending order when selecting lohi option', () => {
    cy.get('[data-test="product-sort-container"]').select('lohi');

    cy.get('.inventory_item_price').then(($prices) => {
      const prices = [];
      $prices.each((index, element) => {
        const priceText = Cypress.$(element).text().replace('$', '');
        prices.push(parseFloat(priceText));
      });

      const sortedPrices = [...prices].sort((a, b) => a - b);
      expect(prices).to.deep.equal(sortedPrices);
    });
  });

  it('should maintain sorted order when navigating between pages and returning', () => {
    cy.get('[data-test="product-sort-container"]').select('lohi');

    cy.get('.inventory_item_price').then(($prices) => {
      const initialPrices = [];
      $prices.each((index, element) => {
        const priceText = Cypress.$(element).text().replace('$', '');
        initialPrices.push(parseFloat(priceText));
      });

      const sortedPrices = [...initialPrices].sort((a, b) => a - b);
      expect(initialPrices).to.deep.equal(sortedPrices);
    });

    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-test="shopping-cart-link"]').click();
    cy.get('[data-test="continue-shopping"]').click();

    cy.get('[data-test="product-sort-container"]').should('have.value', 'lohi');

    cy.get('.inventory_item_price').then(($prices) => {
      const returnedPrices = [];
      $prices.each((index, element) => {
        const priceText = Cypress.$(element).text().replace('$', '');
        returnedPrices.push(parseFloat(priceText));
      });

      const sortedPrices = [...returnedPrices].sort((a, b) => a - b);
      expect(returnedPrices).to.deep.equal(sortedPrices);
    });
  });

  it('should display all products with valid price format after sorting', () => {
    cy.get('[data-test="product-sort-container"]').select('lohi');

    cy.get('.inventory_item_price').should('have.length.greaterThan', 0);

    cy.get('.inventory_item_price').each(($price) => {
      const priceText = $price.text();
      expect(priceText).to.match(/^\$\d+\.\d{2}$/);
    });
  });
});
